import requests

def fetch_user(user_id):
    try:
        r = requests.get(f"https://httpbin.org/status/{user_id}", timeout=5)
        r.raise_for_status()
        return "ok"
    except requests.HTTPError as err:
        code = err.response.status_code
        return "not found" if code == 404 else f"server said {code}"
    except (requests.ConnectionError, requests.Timeout) as err:
        return f"unreachable: {type(err).__name__}"

print(fetch_user(200))   # ok
print(fetch_user(404))   # not found
print(fetch_user(503))   # server said 503

try:
    requests.get("httpbin.org/get", timeout=5)
except requests.exceptions.MissingSchema as e:
    print(type(e).__name__)   # MissingSchema
print(issubclass(requests.ConnectTimeout, requests.Timeout))  # True

import requests
import responses

def get_temperature(city, session=requests):
    r = session.get("https://api.example.com/weather", params={"city": city}, timeout=5)
    r.raise_for_status()
    return r.json()["temp"]

@responses.activate
def test_weather():
    responses.get("https://api.example.com/weather", json={"temp": 21.5})
    assert get_temperature("Yerevan") == 21.5
    assert responses.calls[0].request.params == {"city": "Yerevan"}

    responses.get("https://api.example.com/weather", status=503)
    try:
        get_temperature("Paris")
    except requests.HTTPError as e:
        print("handled", e.response.status_code)   # handled 503

test_weather()
print("ok")   # ok
